def chunk_array(array, size):
    if size <= 0:
        return []
    return [array[i:i+size] for i in range(0, len(array), size)]

def process_lines(text, transform_fn):
    lines = text.split('\n')
    return [transform_fn(line) for line in lines if line.strip()]

def batch_process(items, batch_size, process_fn):
    chunks = chunk_array(items, batch_size)
    return [process_fn(chunk) for chunk in chunks]

